#!/usr/bin/env bash

# AI-Generated Code Evaluation
# Generated by: ChatGPT 
# Modified by: Henry Alvarez
# Citations:
#   - journalctl and ss commands: CIS 245 Week 8 Lecture
#   - awk -F: command structure: CIS 245 Awk Lab
#   - Bash scripting syntax: CIS 117 Intro to Linux
#   - tee command for output redirection: https://linuxize.com/post/linux-tee-command/


###############################################################################
# Linux Security Audit Script
#
# Supported operating systems:
#   - CentOS Stream 10
#   - Ubuntu 26.04
#
# Purpose:
#   - Report failed SSH logins during the last 24 hours.
#   - Identify accounts with UID 0.
#   - Identify accounts with empty passwords.
#   - List listening TCP and UDP ports.
#   - Save results to /var/log/security_audit/.
#
# Exit codes:
#   0 = No security findings or audit errors.
#   1 = Security findings or audit errors detected.
#   2 = Unable to initialize the report.
#
###############################################################################

# Do not allow errors to expose sensitive information through permissive files.
umask 077

# Track whether any security findings or audit errors occur.
ISSUES_FOUND=0

# Define the report directory.
LOG_DIR="/var/log/security_audit"

# Generate a timestamped report filename.
TIMESTAMP=$(date '+%Y-%m-%d_%H-%M-%S')
REPORT="$LOG_DIR/security_audit_$TIMESTAMP.log"

###############################################################################
# SECTION 1: Initialize the report directory and output file
###############################################################################

# Create the report directory if it does not already exist.
if ! mkdir -p "$LOG_DIR"; then
    echo "ERROR: Cannot create $LOG_DIR"
    exit 2
fi

# Redirect all output into the report.
exec > "$REPORT" 2>&1

echo "============================================================"
echo "             LINUX SECURITY AUDIT REPORT"
echo "============================================================"
echo "Hostname: $(hostname)"
echo "Date: $(date)"
echo "Report: $REPORT"
echo "============================================================"

###############################################################################
# SECTION 2: Check failed SSH logins during the last 24 hours
###############################################################################

echo
echo "============================================================"
echo "SECTION 1: FAILED SSH LOGINS (LAST 24 HOURS)"
echo "============================================================"

# Both supported operating systems use systemd and journalctl.
if command -v journalctl >/dev/null 2>&1; then

    # Retrieve journal entries from the previous 24 hours.
    SSH_LOGS=$(journalctl --since "24 hours ago" \
        --no-pager -o short-iso 2>/dev/null)
    JOURNAL_STATUS=$?

    if [ "$JOURNAL_STATUS" -ne 0 ]; then
        echo "ERROR: Unable to read the system journal."
        ISSUES_FOUND=1

    else
        # Identify common SSH authentication failure messages.
        FAILED_LOGINS=$(printf '%s\n' "$SSH_LOGS" |
            grep -Ei 'sshd.*(Failed password|Invalid user|authentication failure|Failed publickey|maximum authentication attempts)' || true)

        if [ -n "$FAILED_LOGINS" ]; then
            echo "$FAILED_LOGINS"
            echo
            echo "WARNING: Failed SSH authentication attempts detected."
            ISSUES_FOUND=1
        else
            echo "No failed SSH authentication attempts found."
        fi
    fi

else
    echo "ERROR: journalctl is not installed or available."
    ISSUES_FOUND=1
fi

###############################################################################
# SECTION 3: Identify accounts with root privileges (UID 0)
###############################################################################

echo
echo "============================================================"
echo "SECTION 2: ACCOUNTS WITH ROOT PRIVILEGES (UID 0)"
echo "============================================================"

# Read /etc/passwd and identify all accounts with UID 0.
ROOT_ACCOUNTS=$(awk -F: '$3 == 0 {print $1 " (UID: " $3 ")"}' /etc/passwd)

if [ -n "$ROOT_ACCOUNTS" ]; then
    echo "$ROOT_ACCOUNTS"

    # The root account itself is expected.
    # Additional UID 0 accounts should be investigated.
    EXTRA_ROOT=$(awk -F: '$3 == 0 && $1 != "root" {print $1}' /etc/passwd)

    if [ -n "$EXTRA_ROOT" ]; then
        echo
        echo "WARNING: Additional accounts have UID 0:"
        echo "$EXTRA_ROOT"
        ISSUES_FOUND=1
    fi
else
    echo "ERROR: No UID 0 accounts found."
    ISSUES_FOUND=1
fi

###############################################################################
# SECTION 4: Identify accounts with empty passwords
###############################################################################

echo
echo "============================================================"
echo "SECTION 3: ACCOUNTS WITH EMPTY PASSWORDS"
echo "============================================================"

# /etc/shadow normally requires root privileges to read.
if [ -r /etc/shadow ]; then

    # An empty second field means the password field is empty.
    EMPTY_PASSWORDS=$(awk -F: '$2 == "" {print $1}' /etc/shadow)

    if [ -n "$EMPTY_PASSWORDS" ]; then
        echo "WARNING: Accounts with empty password fields:"
        echo "$EMPTY_PASSWORDS"
        ISSUES_FOUND=1
    else
        echo "No accounts with empty password fields found."
    fi

else
    echo "ERROR: Cannot read /etc/shadow."
    echo "Run this script as root."
    ISSUES_FOUND=1
fi

###############################################################################
# SECTION 5: List listening network ports
###############################################################################

echo
echo "============================================================"
echo "SECTION 4: LISTENING TCP AND UDP PORTS"
echo "============================================================"

# Use ss to display listening TCP and UDP sockets.
if command -v ss >/dev/null 2>&1; then

    echo
    echo "Listening TCP and UDP sockets:"
    echo

    if ! ss -lntu; then
        echo "ERROR: Unable to retrieve listening ports."
        ISSUES_FOUND=1
    fi

else
    echo "ERROR: ss command is unavailable."
    ISSUES_FOUND=1
fi

###############################################################################
# SECTION 6: Final audit summary
###############################################################################

echo
echo "============================================================"
echo "                 SECURITY AUDIT SUMMARY"
echo "============================================================"

if [ "$ISSUES_FOUND" -eq 0 ]; then
    echo "RESULT: No security findings or audit errors detected."
    echo "EXIT STATUS: 0"
else
    echo "RESULT: Security findings or audit errors detected."
    echo "EXIT STATUS: 1"
fi

echo
echo "Audit completed: $(date)"
echo "Report saved to: $REPORT"
echo "============================================================"

###############################################################################
# SECTION 7: Return appropriate exit code
###############################################################################

exit "$ISSUES_FOUND"
